content:
通过 Package Manager 安装（本地）

打开 Unity 项目的 Packages/manifest.json，添加以下内容。

{
  "dependencies": {
    "com.achieve.utils": "file:../Packages/AchUtils"
  }
}

或选择 Package Manager → Add package from disk，打开 Packages/AchUtils/package.json。

通过 Git URL 安装

{
  "dependencies": {
    "com.achieve.utils": "https://github.com/achieveonepark/AchUtils.git"
  }
}

确认

安装后，在 Assembly Browser 中能看到 AchUtils.Runtime 和 AchUtils.Extensions 即完成。

using AchUtils.Tutorial;
using AchUtils.Buff;
using AchUtils;
// ... 只 using 需要的系统

支持环境

项目	要求
Unity	2021.3 LTS 及以上
.NET	Standard 2.1
平台	iOS, Android, PC, WebGL, Console
外部包	com.unity.ugui, com.unity.nuget.newtonsoft-json

导入示例

在 Package Manager 中选择 AchUtils 包，点击 Samples → Basic Usage → Import，即可把基于实例的使用示例导入到项目中。

# 행동 기록 / 재생 시스템

플레이어의 입력을 타임스탬프 프레임으로 기록하고 원하는 속도로 재생합니다. 고스트 레이싱, 리플레이, AI 학습 데이터, 버그 재현에 활용합니다.

구조

ActionRecorder (순수 C# 인스턴스)
  — 입력 발생 시 InputFrame을 ReplayData에 추가

ActionPlayer (순수 C# 인스턴스)
  — Tick(deltaTime)으로 ReplayData를 재생하고 OnFrame 이벤트 발행

InputFrame (struct)
  — Timestamp, ActionKey, Axis, IsPressed

ReplayData (class)
  — TotalDuration + List<InputFrame>

빠른 시작

1. 기록

using AchUtils.ActionReplay;

private readonly ActionRecorder recorder = new();

// 기록 시작
recorder.StartRecording();

// 입력 발생 시 기록
public void OnJumpPressed()
{
    recorder.RecordButton("Jump", pressed: true);
    // 실제 점프 실행 ...
}

public void OnMove(Vector2 axis)
{
    recorder.RecordAxis("Move", axis);
}

// 기록 종료
ReplayData data = recorder.StopRecording();
SaveReplay(data);   // 직렬화해서 파일/서버에 저장

2. 재생

private readonly ActionPlayer player = new();

void Update()
{
    player.Tick(Time.deltaTime);
}

void PlayGhost(ReplayData data)
{
    player.OnFrame += HandleFrame;
    player.Play(data, speed: 1f);
}

void HandleFrame(InputFrame frame)
{
    switch (frame.ActionKey)
    {
        case "Jump":  ghost.Jump();         break;
        case "Move":  ghost.Move(frame.Axis); break;
        case "Attack": ghost.Attack();      break;
    }
}

player.OnCompleted += () =>
{
    Debug.Log("리플레이 완료");
    player.OnFrame -= HandleFrame;
};

API

ActionRecorder

bool        IsRecording
ReplayData  LastRecording

void        StartRecording()
ReplayData  StopRecording()

// 이벤트 기록
void RecordButton(string key, bool pressed)
void RecordAxis(string key, Vector2 axis)
void Record(string key, Vector2 axis = default, bool pressed = true)

ActionPlayer

bool IsPlaying

void Play(ReplayData data, float speed = 1f)
void Stop()
void Tick(float deltaTime)

event Action<InputFrame> OnFrame       // 매 프레임 발행
event Action             OnCompleted
event Action             OnStopped

InputFrame

float   Timestamp   // 기록 시작부터의 경과 시간 (초)
string  ActionKey   // 액션 이름
Vector2 Axis        // 아날로그 입력 값
bool    IsPressed   // 버튼 누름 여부

재생 속도 조절

player.Play(data, speed: 0.5f);  // 슬로우모션 리플레이
player.Play(data, speed: 2.0f);  // 2배속 요약

데이터 직렬화 / 저장

ReplayData는 [Serializable]이므로 JSON으로 변환해 저장할 수 있습니다.

// 저장
string json = JsonUtility.ToJson(data);
File.WriteAllText("replay.json", json);

// 불러오기
string json = File.ReadAllText("replay.json");
ReplayData data = JsonUtility.FromJson<ReplayData>(json);

활용 사례

용도	설명
고스트 레이싱	최고 기록 플레이를 반투명 오브젝트로 재생
리플레이 시스템	죽음 직전 장면을 다시 보기
AI 학습 데이터	인간 플레이 기록을 모방 학습에 사용
버그 재현	QA가 발견한 버그를 입력 기록으로 완벽 재현
유튜브 클립	하이라이트 장면 자동 편집

# 버프 / 디버프 시스템

Duration, Stack, Tick, 우선순위를 설정하는 범용 버프 관리 파이프라인입니다. 독, 빙결, 공속 증가 등 어떤 효과든 BuffEffect를 상속해 추가합니다.

구조

BuffSystem (순수 C# 인스턴스)
  — 등록된 버프의 타이머·틱·만료 자동 처리

BuffDefinition (ScriptableObject)
  — 이름, 아이콘, Duration, Tick, Stack 설정
  [SerializeReference] List<BuffEffect>

BuffInstance (runtime)
  — 타겟에 적용된 버프의 실행 상태

BuffEffect (abstract, [Serializable])
  ├── DamageOverTimeEffect   — 틱마다 피해
  ├── StunEffect             — 이동 불가
  └── StatModifyEffect       — 스탯 모디파이어 자동 추가/제거

빠른 시작

1. BuffDefinition 에셋 만들기

Create → AchUtils/Buff/Buff Definition

BuffId          : "Poison"
DisplayName     : "독"
Duration        : 8
TickInterval    : 1          ← 1초마다 틱
MaxStacks       : 3
RefreshOnReapply: true

Effects:
  [0] DamageOverTimeEffect
        DamagePerTick: 15

2. BuffSystem 인스턴스 만들기

BuffSystem은 MonoBehaviour가 아니므로 필요한 소유 객체에서 직접 생성합니다. 지속 시간과 틱 처리를 위해 매 프레임 Tick을 호출합니다.

3. 버프 적용 / 제거

using AchUtils.Buff;

private readonly BuffSystem buffSystem = new();

[SerializeField] BuffDefinition poisonDef;
[SerializeField] GameObject target;

void Update()
{
    buffSystem.Tick(Time.deltaTime);
}

// 적용
buffSystem.Apply(poisonDef, target);

// 제거
buffSystem.Remove("Poison", target);

// 확인
bool hasPoisoned = buffSystem.Has("Poison", target);

// 모두 제거
buffSystem.RemoveAll(target);

API

BuffSystem

BuffInstance Apply(BuffDefinition definition, GameObject target)
bool         Remove(string buffId, GameObject target)
void         RemoveAll(GameObject target)
bool         Has(string buffId, GameObject target)
List<BuffInstance> GetBuffs(GameObject target)

void Tick(float deltaTime)

event Action<BuffInstance> OnBuffApplied
event Action<BuffInstance> OnBuffRemoved

BuffDefinition (Inspector)

필드	설명
BuffId	유일 식별자
Duration	지속 시간 (초). -1 = 영구
TickInterval	틱 간격 (초). 0 = 틱 없음
MaxStacks	최대 중첩 수
RefreshDurationOnReapply	재적용 시 Duration 초기화 여부

BuffInstance

BuffDefinition  Definition
GameObject      Target
int             Stacks
float           RemainingDuration
bool            IsPermanent
bool            IsExpired

내장 이펙트

DamageOverTimeEffect

float DamagePerTick   // 틱당 피해량 (스택에 비례)

타겟에 IDamageable 인터페이스가 필요합니다:

public class Player : MonoBehaviour, IDamageable
{
    public void TakeDamage(float amount)
    {
        hp -= amount;
    }
}

StunEffect

타겟에 IStunnable 인터페이스가 필요합니다:

public class PlayerController : MonoBehaviour, IStunnable
{
    private int _stunCount;

    public void ApplyStun()  => _stunCount++;
    public void RemoveStun() => _stunCount--;

    void Update()
    {
        if (_stunCount > 0) return; // 이동 불가
        // 이동 처리 ...
    }
}

StatModifyEffect

버프 적용/제거 시 StatSheetComponent의 스탯을 자동으로 추가/제거합니다.

// Inspector에서 설정
StatKey      : "Attack"
ModifierType : PercentAdd
Value        : 0.3          // 공격력 +30%

커스텀 이펙트 만들기

[Serializable]
public class FreezeEffect : BuffEffect
{
    public float SlowRatio = 0.5f;

    public override void OnApply(BuffInstance buff, GameObject target)
    {
        var rb = target.GetComponent<Rigidbody>();
        if (rb) rb.velocity *= (1f - SlowRatio);
    }

    public override void OnTick(BuffInstance buff, GameObject target)
    {
        // 매 틱 속도 억제
    }
}

활용 예시

독 (Poison)
  Duration: 8s, TickInterval: 1s, MaxStacks: 3
  DamageOverTimeEffect: 15 × 스택

빙결 (Freeze)
  Duration: 2s, MaxStacks: 1
  StunEffect

광전사 (Berserk)
  Duration: 10s, IsPermanent: false
  StatModifyEffect: Attack PercentAdd +0.5

저주 (Curse)
  Duration: -1 (영구), MaxStacks: 1
  StatModifyEffect: Defense Flat -20

# 카메라 디렉터

게임 이벤트 흐름에 맞춰 카메라 연출을 체인으로 조합합니다. Cinemachine보다 단순하고 게임 이벤트 흐름 중심으로 설계됐습니다.

구조

CameraDirector (MonoBehaviour, 코루틴 실행용)
  — Camera 참조, 액션 시퀀스 실행

CameraAction (abstract, [Serializable])
  ├── ZoomCameraAction    — FOV 변경
  ├── ShakeCameraAction   — 진동
  ├── MoveCameraAction    — 위치 이동
  └── WaitCameraAction    — 대기

빠른 시작

1. 씬에 CameraDirector 추가

CameraDirector 컴포넌트를 씬 오브젝트에 추가합니다. Camera 필드를 비워두면 Camera.main을 자동 사용합니다.

2. 단일 액션 재생

using AchUtils.Camera;

[SerializeField] CameraDirector cameraDirector;

cameraDirector.Play(new ShakeCameraAction
{
    Duration  = 0.5f,
    Intensity = 0.3f,
    Frequency = 30f
});

3. 시퀀스 재생

[SerializeField] CameraDirector cameraDirector;

cameraDirector.PlaySequence(new CameraAction[]
{
    new MoveCameraAction
    {
        FollowTarget = boss.transform,
        Duration     = 1.5f,
        Ease         = AnimationCurve.EaseInOut(0,0,1,1)
    },
    new ZoomCameraAction  { TargetFOV = 35f,   Duration = 0.8f },
    new WaitCameraAction  { Duration  = 2.0f },
    new ShakeCameraAction { Duration  = 0.5f,  Intensity = 0.4f },
    new ZoomCameraAction  { TargetFOV = 60f,   Duration = 1.0f },
});

API

CameraDirector

// 접근
CameraDirector cameraDirector

// 참조 카메라 (없으면 Camera.main)
Camera Camera

// 재생
void Play(CameraAction action)
void PlaySequence(IEnumerable<CameraAction> actions)
void Stop()

bool IsPlaying

event Action OnSequenceCompleted

ZoomCameraAction

float          TargetFOV   // 목표 시야각
float          Duration
AnimationCurve Ease

ShakeCameraAction

float          Duration
float          Intensity           // 진폭 크기
float          Frequency           // 진동 주파수 (Hz)
AnimationCurve AttenuationCurve   // 강도 감쇠 곡선 (기본: 시작 강하게 → 약해짐)

MoveCameraAction

Vector3        Destination     // 목표 위치 (FollowTarget이 없을 때)
Transform      FollowTarget    // 지정 시 해당 위치로 추적
float          Duration
AnimationCurve Ease

WaitCameraAction

float Duration

완료 콜백

cameraDirector.OnSequenceCompleted += () =>
{
    // 카메라 연출 완료 후 게임플레이 재개
    player.EnableControl();
    UI.ShowBossHealthBar();
};

cameraDirector.PlaySequence(bossIntroActions);

커스텀 액션 만들기

[Serializable]
public class RotateCameraAction : CameraAction
{
    public Vector3 TargetAngle;
    public float   Duration;

    public override IEnumerator Execute(CameraDirector director)
    {
        var cam = director.Camera.transform;
        Quaternion startRot = cam.rotation;
        Quaternion endRot   = Quaternion.Euler(TargetAngle);
        float elapsed = 0f;

        while (elapsed < Duration)
        {
            elapsed += Time.deltaTime;
            cam.rotation = Quaternion.Lerp(startRot, endRot, elapsed / Duration);
            yield return null;
        }

        cam.rotation = endRot;
    }
}

연출 예시 — 보스 등장

보스 감지 트리거
  ↓
MoveCameraAction   보스 방향으로 1.5초 이동
  ↓
ZoomCameraAction   FOV 60→35  0.8초
  ↓
WaitCameraAction   2초 대기 (보스 포효)
  ↓
ShakeCameraAction  0.5초 진동
  ↓
ZoomCameraAction   FOV 35→60  1초 (원위치)
  ↓
OnSequenceCompleted → UI 표시

# 조건 그래프

복잡한 게임 조건을 AND / OR / NOT 노드 트리로 데이터화합니다. if 지옥을 없애고 기획자가 인스펙터에서 직접 조건을 구성할 수 있습니다.

구조

ConditionGraph (ScriptableObject)
  └── Root: ConditionNode  [SerializeReference]
              ├── AndConditionNode
              │     ├── CompareConditionNode  Level >= 10
              │     ├── CompareConditionNode  VIP >= 3
              │     └── CompareConditionNode  Tutorial == 1
              └── OrConditionNode
                    ├── CompareConditionNode  HasItem == 1
                    └── ...

빠른 시작

1. ConditionGraph 에셋 만들기

Create → AchUtils/Condition/Condition Graph

인스펙터에서 Root에 [+] 버튼으로 노드를 추가합니다.

2. 조건 평가

using AchUtils.Condition;

// 컨텍스트에 현재 게임 상태 주입
var ctx = new ConditionContext();
ctx.Set("Level", player.Level);
ctx.Set("VIP", player.VipGrade);
ctx.Set("Tutorial", tutorialDone ? 1f : 0f);

// 그래프 평가
bool canOpen = shopConditionGraph.Evaluate(ctx);
shopPanel.SetActive(canOpen);

노드 종류

CompareConditionNode

숫자 값을 비교합니다.

필드	타입	설명
Key	string	컨텍스트 키
Op	CompareOp	비교 연산자
Value	float	비교 대상 값

public enum CompareOp
{
    Equal, NotEqual,
    Greater, GreaterOrEqual,
    Less, LessOrEqual
}

AndConditionNode

자식 노드 모두 true일 때 true.

AND
├ Level >= 10   ✓
├ VIP >= 3      ✓
└ Tutorial == 1 ✓
→ true

OrConditionNode

자식 노드 하나라도 true이면 true.

OR
├ HasFreeItem == 1   ✓
└ HasDiscount == 1   ✗
→ true

NotConditionNode

자식 노드의 결과를 반전합니다.

NOT
└ IsBanned == 1   ✗
→ true

ConditionContext API

var ctx = new ConditionContext();

ctx.Set("Level", 15f);
ctx.Get("Level");       // 15f
ctx.Has("Level");       // true
ctx.Remove("Level");
ctx.Clear();

활용 사례

// 상점 노출 조건
shopGraph.Evaluate(ctx)

// 이벤트 오픈
eventGraph.Evaluate(ctx)

// 업적 달성 조건
achievementGraph.Evaluate(ctx)

// 광고 등장 조건
adGraph.Evaluate(ctx)

커스텀 노드 추가

[Serializable]
public class DateRangeConditionNode : ConditionNode
{
    public string StartDate;  // "2024-12-25"
    public string EndDate;

    public override bool Evaluate(ConditionContext context)
    {
        var now = DateTime.Now;
        return now >= DateTime.Parse(StartDate)
            && now <= DateTime.Parse(EndDate);
    }
}

[SerializeReference]와 [Serializable] 어트리뷰트만 붙이면 인스펙터에서 바로 사용 가능합니다.

AchUtils.Extensions 어셈블리는 AchEngine에서 분리해 온 Unity 런타임 확장 메서드와 작은 유틸리티 클래스 모음입니다.
네임스페이스는 모두 AchUtils로 정리되어 있으므로 사용 파일에서 using AchUtils;만 추가하면 됩니다.

설치 정보

항목	값
어셈블리	AchUtils.Extensions
루트 네임스페이스	AchUtils
폴더	Runtime/Extensions
추가 Unity 패키지	com.unity.ugui, com.unity.nuget.newtonsoft-json

포함 범위

컬렉션

클래스	주요 용도
ArrayExt, ListExt	배열과 리스트 조작
DictionaryExt, MultiDictionary<TKey,TValue>	딕셔너리 편의 기능과 한 키에 여러 값을 담는 컬렉션
IEnumerableExt, IListExt, LinqE	LINQ 보조 메서드와 셔플, 필터링, 변환

Unity 타입

클래스	주요 용도
GameObjectExt, ComponentExt	컴포넌트 검색, 추가, 제거, 계층 탐색
Vector2Ext, Vector3Ext, RectExt	좌표, 크기, 범위 계산
ColorExt, ColorUtils	색상 변환과 Hex 처리
SpriteRendererExt, SpriteAtlasExt	스프라이트 렌더러와 아틀라스 편의 기능

UI

클래스	주요 용도
RectTransformExt	UI 레이아웃 좌표와 앵커 조작
ImageExt, RawImageExt, GraphicExt, TextExt	uGUI 컴포넌트 편의 기능
ButtonClickedEventExt	버튼 클릭 이벤트 래핑

기본 타입과 공통 유틸리티

클래스	주요 용도
StringExt, StringParseExt, StringBuilderExt	문자열 검사, 파싱, 조합
IntExt, UintExt, FloatExt, BoolExt, ByteExt, EnumExt	기본 타입 변환과 검사
ActionExt, FuncExt, DelegateExt, UnityEventExt	콜백과 이벤트 호출 보조
Selectable<T>, SelectableList<T>, SelectableBool	값 변경 콜백을 가진 래퍼
SingleTask, MultiTask, StringAppender	반복 작업과 문자열 조립 보조
PlayerPrefsExt, IJsonExt, IncomingWebhooks	JSON 저장, 직렬화, 웹훅 전송

사용 예시

using AchUtils;
using UnityEngine;

public class ExtensionSample : MonoBehaviour
{
    private void Awake()
    {
        var rb = gameObject.GetOrAddComponent<Rigidbody>();
        gameObject.SetActiveIfNotNull(true);

        var hp = new Selectable<int>(100);
        hp.mChanged += () => Debug.Log($"HP changed: {hp.Value}");
        hp.Value = 80;

        var skills = new MultiDictionary<string, string>();
        skills.Add("warrior", "Slash");
        skills.Add("warrior", "Block");
    }
}

마이그레이션

AchEngine에서 사용하던 코드는 네임스페이스만 바꾸면 됩니다.

- using AchEngine;
+ using AchUtils;

AchEngine.Extensions.ReflectionE와 AchEngine.Extensions.ZciencE 하위 네임스페이스도 각각 AchUtils.Extensions.ReflectionE, AchUtils.Extensions.ZciencE로 이동했습니다.

# 퀘스트 시스템

Kill → Talk → Collect 스텝을 조합하는 범용 퀘스트 파이프라인입니다. RPG부터 캐주얼까지 이벤트 기반으로 진행 상황을 추적합니다.

구조

QuestSystem (순수 C# 인스턴스)
  — 활성 퀘스트 관리, 이벤트 라우팅

QuestDefinition (ScriptableObject)
  — 제목, 설명, 보상 목록
  [SerializeReference] List<QuestStep>

QuestInstance (runtime)
  — 현재 스텝 인덱스, 완료 상태

QuestStep (abstract, [Serializable])
  ├── KillQuestStep     — 특정 적 N마리 처치
  ├── TalkQuestStep     — 특정 NPC와 대화
  └── CollectQuestStep  — 특정 아이템 N개 수집

